def solve(nums):
    """Return length of longest strictly increasing subsequence.
    Uses patience sorting with binary search, O(n log n).
    """
    import bisect
    tails = []  # tails[i] = smallest possible tail of an IS of length i+1
    for x in nums:
        # find position to replace: first tail >= x (strictly increasing => use <)
        # we want to place x in the first position where tail >= x, because equal cannot extend.
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

