def solve(weights, values, capacity):
    """0/1 knapsack: return the maximum total value of items with total weight
    not exceeding *capacity*. Handles zero-weight items and returns the best
    value for any weight ≤ capacity.
    """
    # Edge cases
    if capacity < 0:
        return 0
    n = len(weights)
    if n == 0:
        return 0
    # Sum values of zero-weight items (they can always be taken)
    zero_val = 0
    pos_items = []  # (weight, value) with weight > 0
    for w, v in zip(weights, values):
        if w <= 0:
            # weight zero or negative (treat as zero to avoid infinite loops)
            if w == 0:
                zero_val += v
            # ignore negative weights as they break 0/1 assumption
        else:
            pos_items.append((w, v))
    # DP over capacity using 1‑D array
    dp = [0] * (capacity + 1)
    for w, v in pos_items:
        if w > capacity:
            continue
        for c in range(capacity, w - 1, -1):
            new_val = dp[c - w] + v
            if new_val > dp[c]:
                dp[c] = new_val
    # best value for any weight ≤ capacity
    best = max(dp) if dp else 0
    return best + zero_val

