    if not intervals:
        return []
    # Normalize intervals so that start <= end
    norm = []
    for a, b in intervals:
        if a <= b:
            norm.append([a, b])
        else:
            norm.append([b, a])
    # Sort by start
    norm.sort(key=lambda x: x[0])
    merged = []
    cur_start, cur_end = norm[0]
    for s, e in norm[1:]:
        if s <= cur_end:
            cur_end = max(cur_end, e)
        else:
            merged.append([cur_start, cur_end])
