def solve(tokens):
    """Evaluate an expression in Reverse Polish Notation.
    Supports the operators '+', '-', '*', '/' where division truncates toward zero.
    Tokens are strings representing integers or operators.
    """
    stack = []
    for tok in tokens:
        if tok in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if tok == '+':
                res = a + b
            elif tok == '-':
                res = a - b
            elif tok == '*':
                res = a * b
            else:  # division truncates toward zero
                # Python's // truncates toward -inf, so adjust sign.
                if b == 0:
                    raise ZeroDivisionError('division by zero')
                if a * b >= 0:
                    res = a // b
                else:
                    res = -(abs(a) // abs(b))
            stack.append(res)
        else:
            stack.append(int(tok))
    return stack[0] if stack else 0

